export default JSON.parse("{\"schema\":\"ai-brain.semantic-merge.v1\",\"id\":\"values-and-priorities-list-in-my-own-wise-mind-i-believe-it-is-important-to-a-at-2f764a039e34\",\"title\":\"Values and Priorities List In my own Wise Mind, I believe it is important to: \\u0003 \u0089 A. Attend to relationships.\",\"domain\":\"dbt\",\"relatedDomains\":[\"dbt\"],\"purpose\":\"handout\",\"capabilities\":[\"dbt\",\"reference\",\"research\"],\"similarityReview\":{\"threshold\":0.75,\"pairScores\":[0.9862,0.7928,0.7825],\"method\":\"5-token shingle Jaccard within same explicit purpose/title context\"},\"provenance\":{\"mergePolicy\":\"shared structure/content consolidated; unique list items/fields retained; scalar conflicts retained as _merged_values\",\"sources\":[{\"sourcePath\":\"Unified_AI-Brain_PART_2_of_6/AI-Brain/json/therapy_dbt/04-dbt-emotion-regulation-emotion-regulation-handout-18-values-and-priorities-list-in-my-own-6c57d2607a.json\",\"sha256\":\"6c57d2607ab423b90d02fbaa8a16433993eb63ea328937ed6df5fb8dc78217cc\",\"domain\":\"dbt\",\"bytes\":11826},{\"sourcePath\":\"Unified_AI-Brain_PART_2_of_6/AI-Brain/json/therapy_dbt/emotion-regulation-handout-18-values-and-priorities-list-in-my-own-wise-mind-i-believe-it-is-77ef342757.json\",\"sha256\":\"77ef3427577061c740ef81e21c21b3739db9e11385355e5eba66726e01f697fa\",\"domain\":\"dbt\",\"bytes\":11666},{\"sourcePath\":\"skills/skills/dbt/04_dbt_emotion_regulation_emotion_regulation_handout_18_values_and_priorities_list_in_my_own_wise_m_65a175b2.json\",\"sha256\":\"8d1fa977535e0f28dcd96fab0eee75e00dcde0a973c453088e58b9a37713935f\",\"domain\":\"dbt\",\"bytes\":14763}]},\"data\":{\"pages\":[{\"pdf_page\":277,\"book_page\":\"253\",\"text\":\"253\\nFrom DBT Skills Training Handouts and Worksheets, Second Edition by Marsha M. Linehan. Copyright 2015 by Marsha M. Linehan. Permission\\nto photocopy this handout is granted to purchasers of this book for personal use only (see copyright page for details).\\n\u2610\\nEmotion Regulation Handout 18   (Emotion Regulation Worksheets 10, 12, 13) (p. 1 of 3)\\nValues and Priorities List\\nIn my own Wise Mind, I believe it is important to:\\n\\u0003\\n\u0089 A.\\t Attend to relationships.\\n  1.\\t \uf071\\tRepair old relationships.\\n  2.\\t\uf071\\tReach out for new relationships.\\n  3.\\t\uf071\\tWork on current relationships.\\n  4.\\t\uf071\\tEnd destructive relationships.\\n\\n\uf071\\tOther:\\n\\u0003\\n\u0089 B.\\t Be part of a group.\\n  5.\\t\uf071\\tHave close and satisfying relationships with others.\\n  6.\\t\uf071\\tFeel a sense of belonging.\\n  7.\\t \uf071\\tReceive affection and love.\\n  8.\\t\uf071\\tBe involved and intimate with others; have and keep close friends.\\n  9.\\t\uf071\\tHave a family; stay close to and spend time with family members.\\n10.\\t \uf071\\tHave people to do things with.\\n\\n\uf071\\tOther:\\n\\u0003\\n\u0089 C.\\t Be powerful and able to influence others.\\n11.\\t \uf071\\tHave the authority to approve or disapprove of what people do, or to control how\\nresources are used.\\n12.\\t \uf071\\tBe a leader.\\n13.\\t \uf071\\tMake a great deal of money.\\n14.\\t \uf071\\tBe respected by others.\\n15.\\t \uf071\\tBe seen by others as successful; become well known; obtain recognition and status.\\n16.\\t \uf071\\tCompete successfully with others.\\n17.\\t \uf071\\tBe popular and accepted.\\n\\n\uf071\\tOther:\\n\\u0003\\n\u0089 D.\\t Achieve things in life.\\n18.\\t \uf071\\tAchieve significant goals; be involved in undertakings I believe are significant.\\n19.\\t \uf071\\tBe productive.\\n20.\\t\uf071\\tWork toward goals; work hard.\\n21.\\t \uf071\\tBe ambitious.\\n\\n\uf071\\tOther:\\n(continued on next page)\\nAdapted from Schwartz, S. H. (1992). Universals in the content and structure of values: Theory and empirical tests in 20 countries. In M.\\nZanna (Ed.), Advances in experimental social psychology (Vol. 25, pp.\u00a01\u201365). New York: Academic Press. Copyright 1992 by Academic Press.\\nAdapted by permission of Elsevier B.V.\"},{\"pdf_page\":278,\"book_page\":\"254\",\"text\":\"254\\nEmotion Regulation Handout 18   (p. 2 of 3)\\n\\u0003\\n\u0089 E.\\t Live a life of pleasure and satisfaction.\\n22.\\t\uf071\\tHave a good time.\\n23.\\t\uf071\\tSeek fun and things that give pleasure.\\n24.\\t\uf071\\tHave free time.\\n25.\\t\uf071\\tEnjoy the work I do.\\n\\n\uf071\\tOther:\\n\\u0003\\n\u0089 F.\\t Keep life full of exciting events, relationships, and things.\\n26.\\t\uf071\\tTry new and different things in life.\\n27.\\t \uf071\\tBe daring and seek adventures.\\n28.\\t\uf071\\tHave an exciting life.\\n\\n\uf071\\tOther:\\n\\u0003\\n\u0089 G.\\t Behave respectfully.\\n29.\\t\uf071\\tBe humble and modest; do not draw attention to myself.\\n30.\\t\uf071\\tFollow traditions and customs; behave properly.\\n31.\\t \uf071\\tDo what I am told and follow rules.\\n32.\\t\uf071\\tTreat others well.\\n\\n\uf071\\tOther:\\n\\u0003\\n\u0089 H.\\t Be self-directed.\\n33.\\t\uf071\\tFollow my own path in life.\\n34.\\t\uf071\\tBe innovative, think of new ideas, and be creative.\\n35.\\t\uf071\\tMake my own decisions and be free.\\n36.\\t\uf071\\tBe independent; take care of myself and those I am responsible for.\\n37.\\t \uf071\\tHave freedom of thought and action; be able to act in terms of my own priorities.\\n\\n\uf071\\tOther:\\n\\u0003\\n\u0089 I.\\nBe a spiritual person.\\n38.\\t\uf071\\tMake room in life for spirituality; live life according to spiritual principles.\\n39.\\t\uf071\\tPractice a religion or faith.\\n40.\\t\uf071\\tGrow in understanding of myself, my personal calling, and life\u2019s real purpose.\\n41.\\t \uf071\\tDiscern and do the will of God (or a higher power) and find lasting meaning in life.\\n\\n\uf071\\tOther:\\n\\u0003\\n\u0089 J.\\t Be secure.\\n42.\\t\uf071\\tLive in secure and safe surroundings.\\n43.\\t\uf071\\tBe physically healthy and fit.\\n44.\\t\uf071\\tHave a steady income that meets my own and my family\u2019s basic needs.\\n\\n\uf071\\tOther:\\n(continued on next page)\"},{\"pdf_page\":279,\"book_page\":\"255\",\"text\":\"255\\nEmotion Regulation Handout 18   (p. 3 of 3)\\n\\u0003\\n\u0089 K.\\t Recognize the universal good of all things.\\n45.\\t\uf071\\tBe fair, treat people equally, and provide equal opportunities.\\n46.\\t\uf071\\tUnderstand different people; be open-minded.\\n47.\\t \uf071\\tCare for nature and the environment.\\n\\n\uf071\\tOther:\\n\\u0003\\n\u0089 L.\\t Contribute to the larger community.\\n48.\\t\uf071\\tHelp people and those in need; care for others\u2019 well-being; improve society.\\n49.\\t\uf071\\tBe loyal to friends and devoted to close people; be committed to a group that shares\\nmy beliefs, values, and ethical principles.\\n50.\\t\uf071\\tBe committed to a cause or to a group that has a larger purpose beyond my own.\\n51.\\t \uf071\\tMake sacrifices for others.\\n\\n\uf071\\tOther:\\n\\u0003\\n\u0089 M.\\t Work at self-development.\\n52.\\t\uf071\\tDevelop a personal philosophy of life.\\n53.\\t\uf071\\tLearn and do challenging things that help me grow and mature as a human being.\\n\\n\uf071\\tOther:\\n\\u0003\\n\u0089 N.\\t Have integrity.\\n54.\\t\uf071\\tBe honest, and acknowledge and stand up for my personal beliefs.\\n55.\\t\uf071\\tBe a responsible person; keep my word to others.\\n56.\\t\uf071\\tBe courageous in facing and living life.\\n57.\\t \uf071\\tBe a person who pays debts to others and repairs damage I have caused.\\n58.\\t\uf071\\tBe accepting of myself, others, and life as it is; live without resentment.\\n\\n\uf071\\tOther:\\n\\u0003\\n\u0089 O.\\t Other:\"}],\"copyright_notice\":\"Extracted from user-provided PDF: DBT Skills Training Handouts and Worksheets, Second Edition by Marsha M. Linehan. Respect source copyright and purchaser-use limits.\",\"ourspace_shared_revision_metadata\":{\"source_path\":\"DBT+ADHD Skill Files/04_DBT_Emotion_Regulation/handouts/json/emotion_regulation_handout_18_values_and_priorities_list_in_my_own_wise_mind_i_believe_it_is_importa.json\",\"shared_output_path\":\"shared/04_dbt_emotion_regulation/handouts_json/emotion_regulation_handout_18_values_and_priorities_list_in_my_own_wise_m_65a175b2.json\",\"revised_at_utc\":\"2026-06-26T00:24:16Z\",\"copyright_note\":\"Extracted from user-provided PDF: DBT Skills Training Handouts and Worksheets, Second Edition by Marsha M. Linehan. Respect source copyright and purchaser-use limits.\"},\"source_marker\":\"Emotion Regulation Handout 18   (Emotion Regulation Worksheets 10, 12, 13) (p. 1 of 3)\",\"source_pdf_pages\":[277,278,279],\"fillable_html_created\":false,\"created_at\":\"2026-06-25T17:33:54\",\"json_path\":\"json/items/emotion_regulation/handouts/emotion_regulation_handout_18_values_and_priorities_list_in_my_own_wise_mind_i_believe_it_is_importa.json\",\"item_number\":\"18\",\"full_text\":\"\u2610\\nEmotion Regulation Handout 18   (Emotion Regulation Worksheets 10, 12, 13) (p. 1 of 3)\\nValues and Priorities List\\nIn my own Wise Mind, I believe it is important to:\\n\\u0003\\n\u0089 A.\\t Attend to relationships.\\n  1.\\t \uf071\\tRepair old relationships.\\n  2.\\t\uf071\\tReach out for new relationships.\\n  3.\\t\uf071\\tWork on current relationships.\\n  4.\\t\uf071\\tEnd destructive relationships.\\n\\n\uf071\\tOther:\\n\\u0003\\n\u0089 B.\\t Be part of a group.\\n  5.\\t\uf071\\tHave close and satisfying relationships with others.\\n  6.\\t\uf071\\tFeel a sense of belonging.\\n  7.\\t \uf071\\tReceive affection and love.\\n  8.\\t\uf071\\tBe involved and intimate with others; have and keep close friends.\\n  9.\\t\uf071\\tHave a family; stay close to and spend time with family members.\\n10.\\t \uf071\\tHave people to do things with.\\n\\n\uf071\\tOther:\\n\\u0003\\n\u0089 C.\\t Be powerful and able to influence others.\\n11.\\t \uf071\\tHave the authority to approve or disapprove of what people do, or to control how\\nresources are used.\\n12.\\t \uf071\\tBe a leader.\\n13.\\t \uf071\\tMake a great deal of money.\\n14.\\t \uf071\\tBe respected by others.\\n15.\\t \uf071\\tBe seen by others as successful; become well known; obtain recognition and status.\\n16.\\t \uf071\\tCompete successfully with others.\\n17.\\t \uf071\\tBe popular and accepted.\\n\\n\uf071\\tOther:\\n\\u0003\\n\u0089 D.\\t Achieve things in life.\\n18.\\t \uf071\\tAchieve significant goals; be involved in undertakings I believe are significant.\\n19.\\t \uf071\\tBe productive.\\n20.\\t\uf071\\tWork toward goals; work hard.\\n21.\\t \uf071\\tBe ambitious.\\n\\n\uf071\\tOther:\\n(continued on next page)\\nAdapted from Schwartz, S. H. (1992). Universals in the content and structure of values: Theory and empirical tests in 20 countries. In M.\\nZanna (Ed.), Advances in experimental social psychology (Vol. 25, pp.\u00a01\u201365). New York: Academic Press. Copyright 1992 by Academic Press.\\nAdapted by permission of Elsevier B.V.\\n\\nEmotion Regulation Handout 18   (p. 2 of 3)\\n\\u0003\\n\u0089 E.\\t Live a life of pleasure and satisfaction.\\n22.\\t\uf071\\tHave a good time.\\n23.\\t\uf071\\tSeek fun and things that give pleasure.\\n24.\\t\uf071\\tHave free time.\\n25.\\t\uf071\\tEnjoy the work I do.\\n\\n\uf071\\tOther:\\n\\u0003\\n\u0089 F.\\t Keep life full of exciting events, relationships, and things.\\n26.\\t\uf071\\tTry new and different things in life.\\n27.\\t \uf071\\tBe daring and seek adventures.\\n28.\\t\uf071\\tHave an exciting life.\\n\\n\uf071\\tOther:\\n\\u0003\\n\u0089 G.\\t Behave respectfully.\\n29.\\t\uf071\\tBe humble and modest; do not draw attention to myself.\\n30.\\t\uf071\\tFollow traditions and customs; behave properly.\\n31.\\t \uf071\\tDo what I am told and follow rules.\\n32.\\t\uf071\\tTreat others well.\\n\\n\uf071\\tOther:\\n\\u0003\\n\u0089 H.\\t Be self-directed.\\n33.\\t\uf071\\tFollow my own path in life.\\n34.\\t\uf071\\tBe innovative, think of new ideas, and be creative.\\n35.\\t\uf071\\tMake my own decisions and be free.\\n36.\\t\uf071\\tBe independent; take care of myself and those I am responsible for.\\n37.\\t \uf071\\tHave freedom of thought and action; be able to act in terms of my own priorities.\\n\\n\uf071\\tOther:\\n\\u0003\\n\u0089 I.\\nBe a spiritual person.\\n38.\\t\uf071\\tMake room in life for spirituality; live life according to spiritual principles.\\n39.\\t\uf071\\tPractice a religion or faith.\\n40.\\t\uf071\\tGrow in understanding of myself, my personal calling, and life\u2019s real purpose.\\n41.\\t \uf071\\tDiscern and do the will of God (or a higher power) and find lasting meaning in life.\\n\\n\uf071\\tOther:\\n\\u0003\\n\u0089 J.\\t Be secure.\\n42.\\t\uf071\\tLive in secure and safe surroundings.\\n43.\\t\uf071\\tBe physically healthy and fit.\\n44.\\t\uf071\\tHave a steady income that meets my own and my family\u2019s basic needs.\\n\\n\uf071\\tOther:\\n(continued on next page)\\n\\nEmotion Regulation Handout 18   (p. 3 of 3)\\n\\u0003\\n\u0089 K.\\t Recognize the universal good of all things.\\n45.\\t\uf071\\tBe fair, treat people equally, and provide equal opportunities.\\n46.\\t\uf071\\tUnderstand different people; be open-minded.\\n47.\\t \uf071\\tCare for nature and the environment.\\n\\n\uf071\\tOther:\\n\\u0003\\n\u0089 L.\\t Contribute to the larger community.\\n48.\\t\uf071\\tHelp people and those in need; care for others\u2019 well-being; improve society.\\n49.\\t\uf071\\tBe loyal to friends and devoted to close people; be committed to a group that shares\\nmy beliefs, values, and ethical principles.\\n50.\\t\uf071\\tBe committed to a cause or to a group that has a larger purpose beyond my own.\\n51.\\t \uf071\\tMake sacrifices for others.\\n\\n\uf071\\tOther:\\n\\u0003\\n\u0089 M.\\t Work at self-development.\\n52.\\t\uf071\\tDevelop a personal philosophy of life.\\n53.\\t\uf071\\tLearn and do challenging things that help me grow and mature as a human being.\\n\\n\uf071\\tOther:\\n\\u0003\\n\u0089 N.\\t Have integrity.\\n54.\\t\uf071\\tBe honest, and acknowledge and stand up for my personal beliefs.\\n55.\\t\uf071\\tBe a responsible person; keep my word to others.\\n56.\\t\uf071\\tBe courageous in facing and living life.\\n57.\\t \uf071\\tBe a person who pays debts to others and repairs damage I have caused.\\n58.\\t\uf071\\tBe accepting of myself, others, and life as it is; live without resentment.\\n\\n\uf071\\tOther:\\n\\u0003\\n\u0089 O.\\t Other:\",\"source_pdf\":\"DBT Skills Workbook.pdf\",\"related_references\":[\"Emotion Regulation Worksheets 10, 12, 13\"],\"id\":\"emotion_regulation_handout_18\",\"ourspace_shared_life_filter\":{\"revision_id\":\"ourspace_shared_life_filter_v1\",\"title\":\"Values and Priorities List In my own Wise Mind, I believe it is important to: \\u0003 \u0089 A. Attend to relationships.\",\"domain\":\"emotion_regulation\",\"item_type\":\"handout\",\"shared_facing_summary\":\"Emotion work starts with the body and access needs. Hunger, pain, oxygen, sleep attacks, MCAS reactions, trauma cues, and exhaustion count.\",\"tiny_steps\":[\"Name the emotion.\",\"Check body basics: breathing, pain, food/water, meds, temperature, sensory load.\",\"Lower the demand by one size.\",\"Choose soothe, solve, pause, or ask for help.\"],\"flare_day_versions\":{\"minimum\":\"One breath, one label, one safe message, or one checkbox.\",\"medium\":\"Two to five minutes with everything reachable from bed/chair.\",\"full\":\"Use the original worksheet/handout when both bodies and brains have capacity.\"},\"accessibility_modifications\":[\"Use low-exertion regulation first.\",\"Allow anger and grief without turning them into shame.\",\"Track patterns without moral judgment.\"],\"relationship_and_caregiver_notes\":[\"William's needs and Jasper's capacity both count.\",\"Ask before helping; ask before escalating; name the smallest next step.\",\"Pause means pause, not abandonment. I am coming back. I care about us. I need a smaller next step.\",\"What is needed, what capacity exists, what can be smaller, and what can wait?\"],\"identity_and_trauma_filter\":[\"Use William's masculine language and Jasper's they/them language.\",\"Use consent-based, non-shaming, body-neutral language unless a person has explicitly chosen a term.\",\"Do not turn symptoms, dysphoria, trauma responses, clutter, fatigue, or emotional intensity into moral failure.\"],\"avoid_or_adjust\":[\"Do not demand immediate calm during respiratory distress, pain flares, dissociation, or overload.\"],\"suggested_cadence\":[\"daily_optional\",\"flare_day_as_needed\"],\"app_tags\":[\"adhd_friendly\",\"disability_first\",\"emotion_regulation\",\"shared\",\"tiny_steps\",\"trauma_informed\"]},\"item_type\":\"handout\",\"is_example\":false,\"source_book_pages\":[\"253\",\"254\",\"255\"],\"title\":\"Values and Priorities List In my own Wise Mind, I believe it is important to: \\u0003 \u0089 A. Attend to relationships.\",\"module_category\":\"Emotion Regulation Skills\",\"shared_json_path\":\"shared/04_dbt_emotion_regulation/handouts_json/emotion_regulation_handout_18_values_and_priorities_list_in_my_own_wise_m_65a175b2.json\",\"module\":\"Emotion Regulation\",\"keywords\":[\"Attend\",\"List\",\"Mind\",\"Priorities\",\"Values\",\"Wise\",\"believe\",\"important\",\"relationships\"]}}");
